# =============================================================================
# replication_core_spec.R -- FULL REPLICATION of the core specification (Sam, 29 Sep 2026, second layout). For inspection and
# refinement before it replaces the manuscript scripts. Nothing here writes to any document.
#
# Core specification (7 parameters):  mig_gross_t = a + rho mig_gross_{t-1} + b delta_oadr_10_t + c L_tax_workpop + d L_ln_debt_gdp
#                                                   + e L_ln_vac_unem + f L_ln_int_tme + u_t
#   mig_gross      log gross inflow, persons. Citizen sample: non-British citizens (LTIM 2.00) to 1974, non-EU citizens from non-EU
#                  residence (IPS 3.01) from 1975, no basis step. Origin sample: non-EU citizens from non-EU residence throughout.
#   delta_oadr_10  projected 10-year change in the old-age dependency ratio, latest projection with base year <= t
#   L_tax_workpop  national accounts taxes per working-age person, GBP 000 at 2024-25 prices, t-1 (revenue / political constraint)
#   L_ln_debt_gdp  annual log change in public sector net debt / GDP, t-1 (long-term capacity)
#   L_ln_vac_unem  log of notified vacancies / unemployment, t-1 (labour market; contains unemployment)
#   L_ln_int_tme   log of public sector debt interest / TME, t-1, Millennium vintage (short-term fiscal capacity)
# Samples: the Citizen sample (1964-2019; estimation 1965-2019 after the lag, N 55) and the Origin sample (1977-2019, N 43).
# Layout: 1 main results in full (Table 1 Citizen, Table 1.1 Origin, Table 1.3 citizenship against country of last residence on the
# same years); 2 the mechanism (with and without the projection; work permits; inflows by main reason); 3 the projection (total DR
# against the old-age ratio; level against change; horizon); 4 non-economic robustness (alternative projections: publication-dated,
# zero-migration; dynamics: second lag, timing placebo; regime steps; stability over time); 5 the economic regressors (tax measure;
# labour-market term; the fiscal term against bills, term spread, gilts, none; wage inflation and the balance of payments);
# 6 alternative outcomes (settlement grants, LTIM, citizenship classification); 7 uncontrolled flows (EU and British citizens, all in
# log persons; the cycle; British by reason; push events).
# Every alternative outcome is in log persons, like the main. Column titles name only the variable added or substituted.
# BOOT (default TRUE): recursive bootstrap of the projection's t statistic and bootstrap RESET in Tables 1 and 1.1 (R = 999, ~1 min each).
# EXACT (default FALSE): exact ARDL bounds critical values (slow). DATA: Dissertation_Dataset_Final.xlsx only.
# RStudio: Session > Set Working Directory > To Source File Location, then source() this file (not Compile Report).
# =============================================================================
if (!file.exists("tables_common.R")) stop("set the working directory to diss_replication/ (RStudio: Session > Set Working Directory > To Source File Location). Run this file with source(), not with RStudio's Compile Report button, which runs it from the file's own folder.")
if (!exists("BOOT")) BOOT <- TRUE; if (!exists("EXACT")) EXACT <- FALSE
options(restud.rebuild = FALSE, restud.secondary = FALSE)   # read the workbook sheets; no re-estimation-to-2016 lines (everything runs to 2019)
if (exists("REBUILD_DATA", envir = globalenv())) { cat("note: a REBUILD_DATA variable in the global environment is ignored (removed)\n"); rm(REBUILD_DATA, envir = globalenv()) }
suppressPackageStartupMessages(library(readxl)); .wb <- "Dissertation_Dataset_Final.xlsx"; if (!file.exists(.wb)) stop("Dissertation_Dataset_Final.xlsx is not in the working directory ", getwd())
.sh <- excel_sheets(.wb); cat("working directory:", getwd(), "\nworkbook:", normalizePath(.wb), "(", format(file.info(.wb)$mtime), ")\nsheets:", paste(.sh, collapse = ", "), "\n")
if (!all(c("data_1964", "data_1977") %in% .sh)) stop("The workbook lacks the assembled data sheets data_1964 / data_1977. They are written by export_dataset.R and committed with the workbook: pull the latest Dissertation_Dataset_Final.xlsx from the repository.")
options(warn = 1)
.need <- c("brit_gross", "eu_gross", "nb_gross", "brit_desc_gross", "gap_obr", "settle_total_k", "res_noneu_k", "cit_noneu_k", "term_spread", "tme_obr_gdp", "unem_diff", "noneu_work_k", "brit_work_k", "p_pub_ext")
.have <- names(read_excel(.wb, sheet = "data_1977", n_max = 1, .name_repair = "minimal")); if (!all(.need %in% .have)) stop("The data sheets in this workbook are older than this script: missing ", paste(setdiff(.need, .have), collapse = ", "), ". Pull the latest Dissertation_Dataset_Final.xlsx from the repository (or, with the determinants/ folder up to date, run export_dataset.R once).")
source("tables_common.R"); suppressPackageStartupMessages({library(ARDL); library(strucchange); library(tseries)})
LABS <- c(extended = "Citizen sample (1965-2019)", core = "Origin sample (1977-2019)")
load_sample <- function(s) { SAMPLE <<- s; source("data_common.R", local = TRUE); df$ln_vac_unem <- log(df$vac_unem); df$ln_int_tme <- log(df$int_tme)
  for (k in c("res_noneu_k", "cit_noneu_k", "dv_noneu_k", "settle_total_k", "settle_push_k")) if (k %in% names(df)) { x <- df[[k]]; x[!is.na(x) & x <= 0] <- NA; nm <- paste0("ln_", sub("_k$", "", k)); df[[nm]] <- log(1000 * x); df[[paste0("L_", nm)]] <- lag1(df[[nm]]) }
  for (v in c("noneu", "brit")) for (r in c("work", "study", "join", "other", "all", "nonwork")) { k <- paste0(v, "_", r, "_k"); if (k %in% names(df)) { x <- df[[k]]; x[!is.na(x) & x <= 0] <- NA; df[[paste0("ln_", v, "_", r)]] <- log(1000 * x); df[[paste0("L_ln_", v, "_", r)]] <- lag1(df[[paste0("ln_", v, "_", r)]]) } }
  df$ltim_gross <- df$ltim_rate + log(lag1(df$workpop) / 1000) - log(1000); df$L_ltim_gross <- lag1(df$ltim_gross)
  list(df = df, Y0 = Y0, LAB = if (s == "1964") LABS[["extended"]] else LABS[["core"]]) }
SMP <- list(extended = load_sample("1964"), core = load_sample("1977")); SMP$extended$LAB <- LABS[["extended"]]; SMP$core$LAB <- LABS[["core"]]
ref <- as.data.frame(read_excel(.wb, sheet = "ReformSPA", .name_repair = "minimal")); ref <- ref[!is.na(ref$year), ]; pub <- as.data.frame(read_excel(.wb, sheet = "PubShiftOADR_ZM", .name_repair = "minimal")); pub <- pub[!is.na(pub$year), ]
for (k in names(SMP)) { d <- SMP[[k]]$df; d$delta_zm_10 <- as.numeric(ref$delta_zm_10)[match(d$year, ref$year)]; d$p_pub <- as.numeric(pub$delta_oadr_10_pub)[match(d$year, pub$year)]; d$L2_mig_gross <- lag1(d$L_mig_gross); SMP[[k]]$df <- d }
DEFS[["delta_zm_10"]] <- "projected ten-year change in the old-age dependency ratio under the zero-migration variant of the same vintage (from 1975)"; DEFS[["p_pub"]] <- "the ten-year projected change dated by publication year rather than base year (from 1978)"
DEFS[["L2_mig_gross"]] <- "mig_gross lagged two years"; DEFS[["post1968"]] <- "indicator from 1968: Commonwealth Immigrants Act 1968 in force"; DEFS[["post1973"]] <- "indicator from 1973: Immigration Act 1971 in force on 1 January 1973"
CT <- c("L_tax_workpop", "L_ln_debt_gdp", "L_ln_vac_unem", "L_ln_int_tme"); G <- c("L_mig_gross", "delta_oadr_10", CT); NP <- setdiff(G, "delta_oadr_10")
DEFS[["ln_res_noneu"]] <- "log inflow of ALL citizenships arriving from non-EU countries of last residence, persons (IPS 3.01): the origin basis"; DEFS[["L_ln_res_noneu"]] <- "ln_res_noneu, t-1"
DEFS[["ln_cit_noneu"]] <- "log inflow of non-EU citizens arriving from ANY country of last residence, persons (IPS 3.01): the citizenship basis"; DEFS[["L_ln_cit_noneu"]] <- "ln_cit_noneu, t-1"
DEFS[["permits"]] <- "work permits and first permissions issued, thousands (Bauer and Salt, 2020, Figure 1, digitised; 1946-2008; the Tier 2 count from 2009 is a different basis and is not spliced)"; DEFS[["L_permits"]] <- "permits, t-1"
DEFS[["ltim_gross"]] <- "log inflow of non-EU citizens on the LTIM basis (IPS adjusted for asylum seekers, visitor and migrant switchers), persons, 1991-2019"; DEFS[["L_ltim_gross"]] <- "ltim_gross, t-1"
DEFS[["nb_gross"]] <- "log inflow of non-British citizens, all origins, persons (LTIM 2.00), 1964-2019: the citizenship classification throughout (EU citizens included)"; DEFS[["L_nb_gross"]] <- "nb_gross, t-1"
DEFS[["nb03_gross"]] <- "nb_gross to 2003 (before the 2004 EU accession)"; DEFS[["L_nb03_gross"]] <- "nb03_gross, t-1"; DEFS[["mig_gross_s"]] <- "mig_gross with the pre-1975 non-British series rescaled by the 1975-80 overlap ratio"; DEFS[["L_mig_gross_s"]] <- "mig_gross_s, t-1"
DEFS[["eu_gross"]] <- "log inflow of EU citizens, all origins, persons (IPS 3.01, from 1975)"; DEFS[["L_eu_gross"]] <- "eu_gross, t-1"; DEFS[["brit_gross"]] <- "log inflow of British citizens, all origins, persons (LTIM 2.00)"; DEFS[["L_brit_gross"]] <- "brit_gross, t-1"
DEFS[["brit_desc_gross"]] <- "log inflow of British citizens from non-EU residence NOT born in the UK, persons (IPS 3.01 minus 3.18)"; DEFS[["L_term_spread"]] <- "10-year gilt yield minus the Treasury bill rate, percentage points, t-1"
DEFS[["ln_settle_total"]] <- "log grants of settlement, all nationalities, persons (Home Office, Control of Immigration Statistics 2006, Table 5.8; 1960-2006)"; DEFS[["L_ln_settle_total"]] <- "ln_settle_total, t-1"
DEFS[["ln_settle_push"]] <- "log grants of settlement to nationals of Hong Kong, Zimbabwe, South Africa, Kenya and Uganda, persons, current year (Home Office retrospective tables, 1983-2007)"; DEFS[["L_ln_settle_push"]] <- "ln_settle_push, t-1"
for (h in c(3, 5, 7)) DEFS[[paste0("delta_oadr_", h)]] <- paste0("projected ", h, "-year change in the old-age dependency ratio, same vintages"); DEFS[["level_oadr_10"]] <- "projected old-age dependency ratio ten years ahead, level"
for (v in c("noneu", "brit")) for (r in c("work", "study", "join", "other", "all", "nonwork")) DEFS[[paste0("ln_", v, "_", r)]] <- paste0("log inflow of ", if (v == "brit") "British" else "non-EU", " citizens whose main reason for migration is ", switch(r, work = "work (definite job or looking for work)", study = "formal study", join = "accompanying or joining", other = "other (including no reason stated)", all = "any reason", nonwork = "not work or study (home, joining, other)"), ", persons (IPS 3.08, 1977-2019)")
hac <- function(m) coeftest(m, vcov. = vcovHAC(m)); pf2 <- function(p) if (p < .001) "<.001" else sprintf("%.3f", p)
bounds <- function(S, xs, dv = "mig_gross") { lev <- sub("^L_", "", setdiff(xs, paste0("L_", dv))); vv <- c(dv, lev); ok <- complete.cases(S[, vv]); ts_df <- ts(S[ok, vv], start = min(S$year[ok]), frequency = 1)
  m_ardl <- ardl(as.formula(paste(dv, "~", paste(lev, collapse = " + "))), data = ts_df, order = rep(1, length(lev) + 1)); bf <- bounds_f_test(m_ardl, case = 3, exact = EXACT); bt <- bounds_t_test(m_ardl, case = 3, exact = EXACT); lr <- multipliers(m_ardl, type = "lr")
  list(F = unname(bf$statistic), Fp = unname(bf$p.value), t = unname(bt$statistic), tp = unname(bt$p.value), lr = lr[lr$Term == "delta_oadr_10", ]) }
oos <- function(S, xs, dv, from) { e <- c(); for (t in from:2019) { tr <- S[S$year < t, ]; te <- S[S$year == t, ]; tr <- tr[complete.cases(tr[, c(dv, xs)]), ]; if (!nrow(te) || anyNA(te[, xs])) next; mm <- lm(reformulate(xs, dv), data = tr); e <- c(e, te[[dv]] - predict(mm, newdata = te)) }; c(rmse = sqrt(mean(e^2)), n = length(e)) }
diag_full <- function(m) { dd <- attr(m, "dd"); cat(sprintf("    RESET(2,3) %s | RESET(2) %s | BG(1) %s | BG(2) %s | BG(3) %s | Ljung-Box(4) %s | rainbow %s | Harvey-Collier %s | Breusch-Pagan %s | Jarque-Bera %s | OLS-CUSUM %s | max VIF %.1f | AIC %.2f | AICc %.2f | N %d\n",
  pf2(resettest(m)$p.value), pf2(resettest(m, power = 2)$p.value), pf2(bgtest(m, 1)$p.value), pf2(bgtest(m, 2)$p.value), pf2(bgtest(m, 3)$p.value), pf2(Box.test(residuals(m), lag = 4, type = "Ljung-Box")$p.value), pf2(raintest(m)$p.value), pf2(tryCatch(harvtest(m)$p.value, error = function(e) NA)), pf2(bptest(m)$p.value), pf2(jarque.bera.test(residuals(m))$p.value),
  pf2(sctest(efp(formula(m), data = dd, type = "OLS-CUSUM"))$p.value), max(vif(m)), AIC(m), AIC(m) + 2 * (length(coef(m)) + 1) * (length(coef(m)) + 2) / (nobs(m) - length(coef(m)) - 2), nobs(m))) }
boot_block <- function(m1, xs0, xs1, R = 999) { dd <- attr(m1, "dd"); m0 <- lm(reformulate(xs0, "mig_gross"), data = dd); b <- coef(m0); X <- model.matrix(m0); rho <- b["L_mig_gross"]; xb <- as.vector(X[, setdiff(colnames(X), "L_mig_gross"), drop = FALSE] %*% b[setdiff(names(b), "L_mig_gross")])
  e0 <- residuals(m0) - mean(residuals(m0)); n <- nrow(dd); tobs <- hac(m1)["delta_oadr_10", 3]; set.seed(20260929)
  ts <- replicate(R, { e <- sample(e0, n, TRUE); y <- numeric(n); yl <- dd$L_mig_gross[1]; for (t in 1:n) { y[t] <- xb[t] + rho * yl + e[t]; yl <- y[t] }; db <- dd; db$mig_gross <- y; db$L_mig_gross <- c(dd$L_mig_gross[1], y[-n]); mb <- lm(reformulate(xs1, "mig_gross"), data = db); coeftest(mb, vcov. = vcovHAC(mb))["delta_oadr_10", 3] })
  Xm <- model.matrix(m1); y0 <- fitted(m1); e1 <- residuals(m1) - mean(residuals(m1)); f0 <- resettest(m1, power = 2)$statistic; fs <- replicate(R, { yb <- y0 + sample(e1, n, TRUE); resettest(lm(yb ~ Xm - 1), power = 2)$statistic })
  cat(sprintf("    recursive residual bootstrap under no projection (R = %d): p(|t| >= %.2f) = %.4f, 5%% critical |t| %.2f; bootstrap RESET(2) p = %.3f (asymptotic %.3f)\n", R, abs(tobs), mean(abs(ts) >= abs(tobs)), quantile(abs(ts), .95), mean(fs >= f0), resettest(m1, power = 2)$p.value)) }
sub_s <- function(k, to = 2019) subset(SMP[[k]]$df, year >= SMP[[k]]$Y0 & year <= to)
main_full <- function(k, tab) { S <- sub_s(k); m <- fit(S, G, "mig_gross"); ct <- hac(m)
  panel(list("main" = m), paste0("Table ", tab, ". The core specification, ", SMP[[k]]$LAB), c("delta_oadr_10", CT, "L_mig_gross"), w = 16, lw = 16, nested_F = TRUE, "Gross inflows in log persons on the lagged inflow, the projection and the four controls; HAC (Newey-West, automatic bandwidth) p-values.")
  cat("  diagnostics:\n"); diag_full(m)
  b <- bounds(S, G); cat(sprintf("  ARDL(1,...) bounds test, PSS case 3%s: F = %.2f (p %s), t = %.2f (p %s); long-run projection %.4f (p %s)\n", if (EXACT) " (exact)" else " (asymptotic)", b$F, pf2(b$Fp), b$t, pf2(b$tp), b$lr$Estimate, pf2(b$lr$`Pr(>|t|)`)))
  sdp <- sd(S$delta_oadr_10[complete.cases(S[, c("mig_gross", G)])]); cat(sprintf("  one SD of the projection (%.2f) raises gross inflows by %.1f%% on impact and %.1f%% in the long run\n", sdp, 100 * (exp(ct["delta_oadr_10", 1] * sdp) - 1), 100 * (exp(b$lr$Estimate * sdp) - 1)))
  from <- if (k == "extended") 1990 else 1997; o1 <- oos(S, G, "mig_gross", from); o0 <- oos(S, NP, "mig_gross", from); cat(sprintf("  recursive one-step forecasts %d-2019 (n %d): RMSE %.4f with the projection, %.4f without, ratio %.2f\n", from, o1["n"], o1["rmse"], o0["rmse"], o1["rmse"] / o0["rmse"]))
  if (BOOT) boot_block(m, NP, G) }
# =============================================================================
cat("\n\n#################### 1. MAIN RESULTS ####################\n"); main_full("extended", "1"); main_full("core", "1.1")
cat("\n--- Table 1.3 Inflow by citizenship against country of last residence, 1977-2019 ---\n")
S <- sub_s("core"); p <- list("citizen" = fit(S, c("L_ln_cit_noneu", "delta_oadr_10", CT), "ln_cit_noneu"), "origin" = fit(S, G, "mig_gross"), "origin (all citizens)" = fit(S, c("L_ln_res_noneu", "delta_oadr_10", CT), "ln_res_noneu"))
panel(p, "Table 1.3. Inflow by citizenship against country of last residence (origin), 1977-2019", c("delta_oadr_10", CT), w = 20, lw = 16, nested_F = TRUE,
      "citizen: non-EU citizens from any country of last residence (the citizenship basis); origin: non-EU citizens arriving from non-EU countries (the main dependent variable); origin (all citizens): everyone arriving from a non-EU country, British and EU citizens included (the country-of-last-residence basis standard in the literature). Same years, same right-hand side.")
D <- S[complete.cases(S[, c("ln_cit_noneu", "mig_gross", "ln_res_noneu")]), c("ln_cit_noneu", "mig_gross", "ln_res_noneu")]; names(D) <- c("citizen", "origin", "origin_all")
cat("  correlation of the three outcomes 1977-2019, log levels:\n"); print(round(cor(D), 3)); cat("  first differences:\n"); print(round(cor(apply(D, 2, diff)), 3))
cat(sprintf("  share of non-EU-citizen arrivals coming from non-EU countries: mean %.2f (min %.2f, max %.2f); share of arrivals from non-EU countries who are non-EU citizens: mean %.2f\n", mean(exp(D$origin - D$citizen)), min(exp(D$origin - D$citizen)), max(exp(D$origin - D$citizen)), mean(exp(D$origin - D$origin_all))))
# =============================================================================
cat("\n\n#################### 2. THE MECHANISM ####################\n")
p <- list(); for (k in names(SMP)) { S <- sub_s(k); nmk <- if (k == "extended") "Citizen" else "Origin"; p[[nmk]] <- fit(S, G, "mig_gross"); p[[paste0(nmk, ", no projection")]] <- fit(S, NP, "mig_gross") }
panel(p, "Table 2.1. With and without the projection, both samples", c("delta_oadr_10", CT, "L_mig_gross"), w = 22, lw = 16, nested_F = TRUE, "The same right-hand side with and without delta_oadr_10; F vs no proj is the classical nested test.")
for (nm in names(p)) { cat("  ", nm, ":\n", sep = ""); diag_full(p[[nm]]) }
for (k in names(SMP)) { S <- sub_s(k); from <- if (k == "extended") 1990 else 1997; o1 <- oos(S, G, "mig_gross", from); o0 <- oos(S, NP, "mig_gross", from); cat(sprintf("  %s: recursive forecasts %d-2019, RMSE %.4f with / %.4f without the projection (ratio %.2f)\n", SMP[[k]]$LAB, from, o1["rmse"], o0["rmse"], o1["rmse"] / o0["rmse"])) }
S <- subset(SMP$extended$df, year >= SMP$extended$Y0 & year <= 2008); p <- list("citizen (to 2008)" = fit(S, G, "mig_gross"), "permits_dv" = fit(S, c("L_permits", "delta_oadr_10", CT), "permits"))
panel(p, "Table 2.2. Work permit grants as the dependent outcome, Citizen sample 1964-2008", c("delta_oadr_10", CT, "L_mig_gross", "L_permits"), w = 18, lw = 16, nested_F = TRUE,
      "permits_dv: work permits and first permissions issued, thousands (Bauer and Salt, 2020, Figure 1, digitised; 1946-2008), the administrative lever, in levels on its own lag and the same right-hand side as the citizen column; the series ends in 2008 because the Tier 2 count from 2009 is a different basis.")
S <- sub_s("core"); p <- list("origin (all)" = fit(S, c("L_ln_noneu_all", "delta_oadr_10", CT), "ln_noneu_all")); for (r in c("work", "study", "join", "other")) { dv <- paste0("ln_noneu_", r); p[[r]] <- fit(S, c(paste0("L_", dv), "delta_oadr_10", CT), dv) }
panel(p, "Table 2.3. Non-EU inflows by main reason for migration (1977-2019)", c("delta_oadr_10", CT), w = 15, lw = 16, nested_F = TRUE, "Each column: the log inflow of non-EU citizens giving the reason named (IPS 3.08), on its own lag, the projection and the controls. The work route is the one the Treasury controls.")
# =============================================================================
cat("\n\n#################### 3. THE PROJECTION ####################\n")
for (k in names(SMP)) { S <- sub_s(k); LAB <- SMP[[k]]$LAB; sw <- function(drop, add) c(setdiff(G, drop), add)
  p <- list("main" = fit(S, G, "mig_gross"), "delta_dr_10" = fit(S, sw("delta_oadr_10", "delta_dr_10"), "mig_gross"), "+delta_dr_10" = fit(S, c(G, "delta_dr_10"), "mig_gross"))
  panel(p, paste0("Table 3.1. The total dependency ratio against the old-age ratio, ", LAB), c("delta_oadr_10", "delta_dr_10", CT), w = 15, lw = 16, nested_F = TRUE, "delta_dr_10: the projected 10-year change in the TOTAL dependency ratio (children + pensioners), the placebo, in place of and beside the old-age projection: the young are not a pension cost.")
  p <- list("main" = fit(S, G, "mig_gross"), "level_oadr_10" = fit(S, sw("delta_oadr_10", "level_oadr_10"), "mig_gross"), "oadr_0" = fit(S, sw("delta_oadr_10", "oadr_0"), "mig_gross"), "+oadr_0" = fit(S, c(G, "oadr_0"), "mig_gross"))
  panel(p, paste0("Table 3.2. Level against change, ", LAB), c("delta_oadr_10", "level_oadr_10", "oadr_0", CT), w = 15, lw = 16, nested_F = TRUE, "level_oadr_10: the projected ratio ten years ahead in place of its change; oadr_0: the current ratio in place of, then beside, the projected change.")
  p <- list("main" = fit(S, G, "mig_gross"), "delta_oadr_3" = fit(S, sw("delta_oadr_10", "delta_oadr_3"), "mig_gross"), "delta_oadr_5" = fit(S, sw("delta_oadr_10", "delta_oadr_5"), "mig_gross"), "delta_oadr_7" = fit(S, sw("delta_oadr_10", "delta_oadr_7"), "mig_gross"))
  panel(p, paste0("Table 3.3. The projection horizon, ", LAB), c("delta_oadr_10", "delta_oadr_3", "delta_oadr_5", "delta_oadr_7", CT), w = 15, lw = 16, "Each column replaces the ten-year projected change by the projected change over the horizon named, same vintages.") }
# =============================================================================
cat("\n\n#################### 4. NON-ECONOMIC ROBUSTNESS ####################\n")
for (k in names(SMP)) { S <- sub_s(k); LAB <- SMP[[k]]$LAB; sw <- function(drop, add) c(setdiff(G, drop), add)
  p <- list("main" = fit(S, G, "mig_gross"), "p_pub_ext" = fit(S, sw("delta_oadr_10", "p_pub_ext"), "mig_gross")); if (k == "core") { p[["p_pub"]] <- fit(S, sw("delta_oadr_10", "p_pub"), "mig_gross"); p[["delta_zm_10"]] <- fit(S, sw("delta_oadr_10", "delta_zm_10"), "mig_gross") }
  panel(p, paste0("Table 4.1. Alternative projections, ", LAB), c("delta_oadr_10", "p_pub_ext", "p_pub", "delta_zm_10", CT), w = 15, lw = 16, nested_F = TRUE,
        "Each column replaces the base-dated projection by the variable named: the publication-dated projection (what was in print in year t; the extended series dates pre-1975 vintages by their publication year, the Origin-sample column uses the sheet from 1978), and the zero-migration variant of the same vintage (the projection with no migration assumed, from 1975).")
  m <- fit(S, G, "mig_gross"); dd <- attr(m, "dd"); t_of <- function(x) { d2 <- dd; d2$pk <- x; mm <- fit(d2, sw("delta_oadr_10", "pk"), "mig_gross"); coeftest(mm, vcov. = vcovHAC(mm))["pk", 3] }
  n <- nrow(dd); t0 <- t_of(dd$delta_oadr_10); tk <- vapply(1:(n - 1), function(j) t_of(c(tail(dd$delta_oadr_10, j), head(dd$delta_oadr_10, -j))), numeric(1))
  p <- list("main" = m, "+L2_mig_gross" = fit(S, c(G, "L2_mig_gross"), "mig_gross"), "lead (t+1)" = { d2 <- S; d2$pk <- c(d2$delta_oadr_10[-1], NA); fit(d2, sw("delta_oadr_10", "pk"), "mig_gross") }, "lag (t-1)" = { d2 <- S; d2$pk <- lag1(d2$delta_oadr_10); fit(d2, sw("delta_oadr_10", "pk"), "mig_gross") })
  DEFS[["pk"]] <- "the projection shifted one year (lead: the following year's projection; lag: the previous year's)"
  panel(p, paste0("Table 4.2. Dynamics and timing, ", LAB), c("delta_oadr_10", "pk", "L2_mig_gross", CT, "L_mig_gross"), w = 15, lw = 16, nested_F = TRUE, "+L2_mig_gross: a second lag of the outcome; lead / lag: the projection shifted forward or back one year in place of the contemporaneous one.")
  cat(sprintf("  timing placebo (the projection series rotated against the outcome, %d rotations): actual HAC t %.2f, largest rotated |t| %.2f, randomisation p = %.3f\n", n - 1, t0, max(abs(tk)), (1 + sum(abs(tk) >= abs(t0))) / n))
  if (k == "extended") { p <- list("main" = fit(S, G, "mig_gross"), "+post1968" = fit(S, c(G, "post1968"), "mig_gross"), "+post1973" = fit(S, c(G, "post1973"), "mig_gross"), "+post1968 +post1973" = fit(S, c(G, "post1968", "post1973"), "mig_gross"), "+basis_pre1975" = fit(S, c(G, "basis_pre1975"), "mig_gross"))
    panel(p, paste0("Table 4.3. Regime steps, ", LAB), c("delta_oadr_10", "post1968", "post1973", "basis_pre1975", CT), w = 16, lw = 16, "Indicators for the Commonwealth Immigrants Act 1968 and the Immigration Act 1971 in force, and for the pre-1975 classification of the outcome (non-British rather than non-EU citizens).") }
  ends <- seq(if (k == "extended") 1990 else 1997, 2019, by = 5); rec <- vapply(ends, function(en) { mm <- fit(subset(S, year <= en), G, "mig_gross"); ct <- coeftest(mm, vcov. = vcovHAC(mm)); sprintf("%.4f (p %s)", ct["delta_oadr_10", 1], pf2(ct["delta_oadr_10", 4])) }, character(1))
  cat(sprintf("  Table 4.4. Stability over time, %s\n    recursive estimates, sample ending %s: %s\n", LAB, paste(ends, collapse = " / "), paste(rec, collapse = " / ")))
  starts <- SMP[[k]]$Y0:(2019 - 24); roll <- t(sapply(starts, function(st) { mm <- fit(subset(S, year >= st & year <= st + 24), G, "mig_gross"); ct <- coeftest(mm, vcov. = vcovHAC(mm)); c(ct["delta_oadr_10", 1], ct["delta_oadr_10", 4]) }))
  fs <- suppressWarnings(Fstats(formula(m), data = dd, from = 0.2)); cat(sprintf("    rolling 25-year windows (starts %d-%d): projection %.4f to %.4f, significant at 5%% in %d of %d; OLS-CUSUM p = %.3f; sup-F for an unknown break (Andrews) = %.2f, p = %.3f\n", min(starts), max(starts), min(roll[, 1]), max(roll[, 1]), sum(roll[, 2] < 0.05), nrow(roll), sctest(efp(formula(m), data = dd, type = "OLS-CUSUM"))$p.value, max(fs$Fstats), sctest(fs)$p.value)) }
