cat("\n\n#################### 5. THE ECONOMIC REGRESSORS ####################\n")
for (k in names(SMP)) { S <- sub_s(k); LAB <- SMP[[k]]$LAB; sw <- function(drop, add) c(setdiff(G, drop), add)
  p <- list("main" = fit(S, G, "mig_gross"), "tax_voter" = fit(S, sw("L_tax_workpop", "L_tax_voter"), "mig_gross"), "tax_res" = fit(S, sw("L_tax_workpop", "L_tax_res"), "mig_gross"), "tax_nics_emp" = fit(S, sw("L_tax_workpop", "L_tax_nics_emp"), "mig_gross"))
  panel(p, paste0("Table 5.1. The tax burden per head, ", LAB), c("delta_oadr_10", "L_tax_workpop", "L_tax_voter", "L_tax_res", "L_tax_nics_emp", "L_ln_debt_gdp", "L_ln_vac_unem", "L_ln_int_tme"), w = 15, lw = 16, "Each column replaces L_tax_workpop by the measure named.")
  p <- list("main" = fit(S, G, "mig_gross"), "unem" = fit(S, sw("L_ln_vac_unem", "L_unem"), "mig_gross"), "unem_boe" = fit(S, sw("L_ln_vac_unem", "L_unem_boe"), "mig_gross"), "+unem" = fit(S, c(G, "L_unem"), "mig_gross"), "ln_vac_wap" = fit(S, sw("L_ln_vac_unem", "L_ln_vac_wap"), "mig_gross"))
  panel(p, paste0("Table 5.2. The labour-market term, ", LAB), c("delta_oadr_10", "L_ln_vac_unem", "L_unem", "L_unem_boe", "L_ln_vac_wap", "L_tax_workpop", "L_ln_debt_gdp", "L_ln_int_tme"), w = 15, lw = 16,
        "Columns 2, 3 and 5 replace log V/U by the variable named; +unem adds the ILO rate beside it. Unemployment is spliced across the 1971 and 1992 changes of measure; the splice does not change the results.")
  p <- list("main" = fit(S, G, "mig_gross"), "none" = fit(S, setdiff(G, "L_ln_int_tme"), "mig_gross"), "int_tme" = fit(S, sw("L_ln_int_tme", "L_int_tme"), "mig_gross"), "ln_int_tme_ons" = fit(S, sw("L_ln_int_tme", "L_ln_int_tme_ons"), "mig_gross"), "tbill" = fit(S, sw("L_ln_int_tme", "L_tbill"), "mig_gross"), "term_spread" = fit(S, sw("L_ln_int_tme", "L_term_spread"), "mig_gross"), "gilt" = fit(S, sw("L_ln_int_tme", "L_gilt"), "mig_gross"), "ln_tme_obr_gdp" = fit(S, sw("L_ln_int_tme", "L_ln_tme_obr_gdp"), "mig_gross"))
  panel(p, paste0("Table 5.3. The fiscal term: debt interest against the cost of borrowing and spending, ", LAB), c("delta_oadr_10", "L_ln_int_tme", "L_int_tme", "L_ln_int_tme_ons", "L_tbill", "L_term_spread", "L_gilt", "L_ln_tme_obr_gdp", "L_tax_workpop", "L_ln_debt_gdp", "L_ln_vac_unem"), w = 15, lw = 16,
        "Each column replaces the log debt-interest share by the variable named (none: drops it). ln_int_tme_ons is the same ratio on the current ONS vintage; ln_tme_obr_gdp is log TME as a share of GDP (OBR databank), the denominator on its own.")
  p <- list("main" = fit(S, G, "mig_gross"), "+wage_infl" = fit(S, c(G, "L_wage_infl"), "mig_gross"), "+ca_gdp" = fit(S, c(G, "L_ca_gdp"), "mig_gross"), "+wage_infl +ca_gdp" = fit(S, c(G, "L_wage_infl", "L_ca_gdp"), "mig_gross"), "+tot" = fit(S, c(G, "L_tot"), "mig_gross"), "+wage_infl +ca_gdp +tot" = fit(S, c(G, "L_wage_infl", "L_ca_gdp", "L_tot"), "mig_gross"))
  panel(p, paste0("Table 5.4. Wage inflation and the balance of payments, ", LAB), c("delta_oadr_10", "L_wage_infl", "L_ca_gdp", "L_tot", CT), w = 16, lw = 16, nested_F = TRUE,
        "The instruments of their era: incomes policy (wage inflation) and the external constraint (current account, terms of trade) were Treasury objectives in the 1960s and 1970s and fade in the later sample; reported as controls of their period, not carried into the specification.") }
