cat("\n\n#################### 6. ALTERNATIVE OUTCOMES ####################\n")
for (k in names(SMP)) { S <- subset(SMP[[k]]$df, year >= SMP[[k]]$Y0 & year <= 2006); p <- list("main (to 2006)" = fit(S, G, "mig_gross"), "settlement" = fit(S, c("L_ln_settle_total", "delta_oadr_10", CT), "ln_settle_total"))
  panel(p, paste0("Table 6.1. Grants of settlement, all nationalities, ", sub("2019", "2006", SMP[[k]]$LAB)), c("delta_oadr_10", CT), w = 16, lw = 16, nested_F = TRUE, "Settlement is the administrative count of permanent admissions of persons subject to control, the narrowest outcome; before the mid-1970s it is dominated by the Commonwealth Immigrants Act regime (dependants and voucher holders), which the Citizen column shows.") }
S <- subset(SMP$core$df, year >= 1991 & year <= 2019); p <- list("main (1991-2019)" = fit(S, G, "mig_gross"), "ltim" = fit(S, c("L_ltim_gross", "delta_oadr_10", CT), "ltim_gross"))
panel(p, "Table 6.2. IPS against LTIM non-EU inflows, Origin sample 1991-2019", c("delta_oadr_10", CT), w = 16, lw = 16, nested_F = TRUE, "LTIM adds asylum seekers and visitor/migrant switchers to the IPS count; available from 1991.")
for (k in names(SMP)) { S <- sub_s(k); p <- list("main" = fit(S, G, "mig_gross"))
  if (k == "extended") { p[["+basis_pre1975"]] <- fit(S, c(G, "basis_pre1975"), "mig_gross"); p[["mig_gross_s"]] <- fit(S, c("L_mig_gross_s", "delta_oadr_10", CT), "mig_gross_s"); p[["nb_gross"]] <- fit(S, c("L_nb_gross", "delta_oadr_10", CT), "nb_gross"); p[["nb03_gross"]] <- fit(subset(S, year <= 2003), c("L_nb03_gross", "delta_oadr_10", CT), "nb03_gross") }
  else { p[["nb_gross"]] <- fit(S, c("L_nb_gross", "delta_oadr_10", CT), "nb_gross"); p[["nb03_gross"]] <- fit(subset(S, year <= 2003), c("L_nb03_gross", "delta_oadr_10", CT), "nb03_gross") }
  panel(p, paste0("Table 6.3. The citizenship classification of the outcome, ", SMP[[k]]$LAB), c("delta_oadr_10", "basis_pre1975", CT), w = 16, lw = 16, nested_F = TRUE, "nb_gross: non-British citizens (LTIM 2.00) throughout, EU citizens included, so the projection is diluted after the 2004 accession; nb03_gross: the same to 2003.") }
# =============================================================================
cat("\n\n#################### 7. UNCONTROLLED FLOWS ####################\n")
S <- sub_s("core"); p <- list("main" = fit(S, G, "mig_gross"), "eu_gross" = fit(S, c("L_eu_gross", "delta_oadr_10", CT), "eu_gross"), "brit_gross" = fit(S, c("L_brit_gross", "delta_oadr_10", CT), "brit_gross"), "+brit_gross" = fit(S, c(G, "brit_gross"), "mig_gross"))
panel(p, "Table 7.1. EU and British inflows on the core controls, Origin sample (1977-2019)", c("delta_oadr_10", "brit_gross", CT, "L_eu_gross", "L_brit_gross", "L_mig_gross"), w = 16, lw = 16, nested_F = TRUE, "eu_gross: EU citizens, whom no British government could ration; brit_gross: British citizens, all origins; +brit_gross holds the British flow constant in the main.")
for (k in names(SMP)) { S <- sub_s(k); BR <- c("L_brit_gross", "delta_oadr_10", CT)
  p <- list("brit_gross" = fit(S, BR, "brit_gross"), "+unem_diff" = fit(S, c(BR, "L_unem_diff"), "brit_gross"), "+cit_nat" = fit(S, c(BR, "cit_nat_k"), "brit_gross"), "+L_gap_obr" = fit(S, c(BR, "L_gap_obr"), "brit_gross"))
  if (k == "core") { p[["brit_desc_gross"]] <- fit(S, c("L_brit_gross", "delta_oadr_10", CT), "brit_desc_gross"); p[["brit_desc +L_gap_obr"]] <- fit(S, c("L_brit_gross", "delta_oadr_10", CT, "L_gap_obr"), "brit_desc_gross") }
  p[["main +L_gap_obr"]] <- fit(S, c(G, "L_gap_obr"), "mig_gross")
  panel(p, paste0("Table 7.2. The British inflow: relative conditions, citizenship policy, the cycle, ", SMP[[k]]$LAB), c("delta_oadr_10", "L_unem_diff", "cit_nat_k", "L_gap_obr", CT, "L_brit_gross", "L_mig_gross"), w = 16, lw = 16, nested_F = TRUE,
        "unem_diff: UK unemployment minus the mean of Australia, Canada, New Zealand and the United States (OECD); cit_nat: naturalisations in the current year (thousands); gap_obr: the OBR output gap (public sector finances databank, fiscal years from 1972-73, so the Citizen columns with it start in 1973); brit_desc_gross: British citizens from non-EU residence not born in the UK; the last column adds the gap to the main equation.") }
S <- sub_s("core"); p <- list(); for (r in c("all", "work", "study", "nonwork")) { dv <- paste0("ln_brit_", r); p[[r]] <- fit(S, c(paste0("L_", dv), "delta_oadr_10", CT), dv) }
panel(p, "Table 7.3. British inflows by main reason for migration (1977-2019)", c("delta_oadr_10", CT), w = 15, lw = 16, nested_F = TRUE, "nonwork = all reasons minus work minus study (going home, accompanying or joining, other), the split coded consistently from 1977.")
BR <- c("L_brit_gross", "delta_oadr_10", CT); Sp <- subset(S, !is.na(settle_push_k))
p <- list("brit_gross (1983-2007)" = fit(Sp, BR, "brit_gross"), "+ln_settle_push" = fit(S, c(BR, "ln_settle_push"), "brit_gross"), "+L_ln_settle_push" = fit(S, c(BR, "L_ln_settle_push"), "brit_gross"), "brit_desc (1983-2007)" = fit(Sp, BR, "brit_desc_gross"), "brit_desc +ln_settle_push" = fit(S, c(BR, "ln_settle_push"), "brit_desc_gross"))
panel(p, "Table 7.4. The British inflow and push-country settlement, Origin sample 1983-2007", c("delta_oadr_10", "ln_settle_push", "L_ln_settle_push", CT, "L_brit_gross"), w = 16, lw = 16, nested_F = TRUE,
      "settle_push: grants of settlement to nationals of Hong Kong, Zimbabwe, South Africa, Kenya and Uganda (Home Office retrospective tables), the flows a push event in those countries would raise; if British citizens by descent left with them, the British inflow would co-move.")
